<?php
namespace Tests\Feature;
use App\Models\{Company,User,Customer,Appointment,ClinicalRecord,FinancialQuote as Quote,FinancialInstallment as Installment,FinancialPayment as Payment,FinancialEvent as Event};
use App\Support\Finance;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Str;
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class FinanceTest extends TestCase {
 use RefreshDatabase;
 private Company $company;private User $owner;private User $reception;private User $dentist;private Customer $patient;
 protected function setUp():void{parent::setUp();$this->company=Company::create(['name'=>'Clínica teste','slug'=>'finance']);$this->owner=$this->user('owner');$this->reception=$this->user('reception');$this->dentist=$this->user('professional');$this->patient=Customer::create(['company_id'=>$this->company->id,'name'=>'Paciente financeiro','active'=>true]);}
 private function user(string $role,?Company $company=null):User{return User::create(['company_id'=>($company??$this->company)->id,'name'=>'Usuário '.$role,'email'=>Str::uuid().'@example.test','password'=>'OnlyTest-12345','role'=>$role,'active'=>true,'clinical_access'=>$role==='professional','professional_registration'=>'CRO-BA 123']);}
 private function form():array{return ['request_id'=>(string)Str::uuid(),'customer_id'=>$this->patient->id,'description'=>'Descrição comercial compartilhada','gross'=>'100,01','discount'=>'0'];}
 private function quote():Quote{$this->flushSession();$this->actingAs($this->owner)->post(route('finance.store'),$this->form())->assertSessionHasNoErrors();return Quote::latest('id')->first();}
 private function approval(Quote $q):array{return ['confirm'=>'1','revision'=>$q->revision,'approved_by_name'=>'Paciente teste','approved_on'=>'2026-01-01','approval_channel'=>'in_person','deposit'=>'0','count'=>3,'first_due'=>'2026-01-31'];}
 private function approved():Quote{$q=$this->quote();$this->post(route('finance.approve',$q->id),$this->approval($q))->assertSessionHasNoErrors();return $q->fresh();}
 private function payment(string $amount='10,00'):array{return ['request_id'=>(string)Str::uuid(),'amount'=>$amount,'paid_on'=>'2026-01-01','method'=>'pix'];}
 private function plan(?array $items=null):ClinicalRecord{Appointment::create(['company_id'=>$this->company->id,'professional_id'=>$this->dentist->id,'customer_id'=>$this->patient->id,'created_by'=>$this->owner->id,'client_name'=>'Paciente','service'=>'Consulta','starts_at'=>'2026-01-01 10:00','ends_at'=>'2026-01-01 10:30','status'=>'completed']);return ClinicalRecord::create(['company_id'=>$this->company->id,'customer_id'=>$this->patient->id,'author_id'=>$this->dentist->id,'author_name'=>'Dentista','author_registration'=>'CRO-BA 123','kind'=>'treatment_plan','occurred_at'=>'2026-01-01 10:00','request_key'=>hash('sha256',(string)Str::uuid()),'payload'=>['title'=>'Segredo do plano','status'=>'active','notes'=>'Diagnóstico secreto','items'=>$items??[['description'=>'Procedimento secreto','region'=>'36','notes'=>'Segredo clínico','quantity'=>2,'unit_price_cents'=>15000,'status'=>'planned']]]]);}
 public function test_manual_quote_discount_encryption_idempotency_and_pages():void{$form=$this->form();$form['discount']='10,01';$this->flushSession();$this->actingAs($this->reception)->post(route('finance.store'),$form)->assertSessionHasNoErrors();$this->post(route('finance.store'),$form)->assertSessionHasNoErrors();$this->assertDatabaseCount('financial_quotes',1);$q=Quote::sole();$this->assertSame(9000,$q->total_cents);$this->assertStringNotContainsString($form['description'],DB::table('financial_quotes')->value('description'));$this->get(route('finance.index'))->assertOk()->assertSee('Paciente financeiro');$this->get(route('finance.create'))->assertOk();$this->get(route('finance.show',$q->id))->assertOk()->assertHeader('Cache-Control','no-store, private');$this->get(route('finance.print',$q->id))->assertOk()->assertSee('Não é nota fiscal');}
 public function test_installment_rounding_dates_deposit_and_full_entry():void{$rows=Finance::schedule(10001,1000,3,'2026-01-31','2026-01-01');$this->assertSame(10001,array_sum(array_column($rows,'amount_cents')));$this->assertSame([1000,3001,3000,3000],array_column($rows,'amount_cents'));$this->assertSame(['2026-01-01','2026-01-31','2026-02-28','2026-03-31'],array_column($rows,'due_on'));$this->assertCount(1,Finance::schedule(10001,10001,24,'2026-01-31','2026-01-01'));}
 public function test_approval_locks_terms_and_duplicate_does_not_create_more_installments():void{$q=$this->quote();$form=$this->approval($q);$this->post(route('finance.approve',$q->id),$form)->assertSessionHasNoErrors();$this->assertSame(10001,(int)Installment::sum('amount_cents'));$this->post(route('finance.approve',$q->id),$form)->assertSessionHasErrors('revision');$this->assertDatabaseCount('financial_installments',3);$this->put(route('finance.update',$q->id),['revision'=>$q->fresh()->revision,'description'=>'Outra','gross'=>'200','discount'=>'0'])->assertSessionHasErrors('revision');}
 public function test_partial_payment_retry_overpayment_and_future_date():void{$q=$this->approved();$i=$q->installments->first();$form=$this->payment();$this->post(route('finance.pay',$i->id),$form)->assertSessionHasNoErrors();$this->post(route('finance.pay',$i->id),$form)->assertSessionHasNoErrors();$this->assertDatabaseCount('financial_payments',1);$this->assertSame(2334,$i->fresh()->balanceCents());$this->post(route('finance.pay',$i->id),$this->payment('24'))->assertSessionHasErrors('amount');$future=$this->payment();$future['paid_on']='2999-01-01';$this->post(route('finance.pay',$i->id),$future)->assertSessionHasErrors('paid_on');$this->post(route('finance.pay',$i->id),$this->payment('23,34'))->assertSessionHasNoErrors();$this->assertSame(0,$i->fresh()->balanceCents());$this->get(route('finance.receipt',Payment::first()->id))->assertOk()->assertSee('Comprovante interno')->assertSee('Não é nota fiscal');}
 public function test_only_owner_reverses_and_cancel_requires_no_live_payment():void{$q=$this->approved();$i=$q->installments->first();$this->post(route('finance.pay',$i->id),$this->payment())->assertSessionHasNoErrors();$p=Payment::sole();$this->post(route('finance.cancel',$q->id),['revision'=>$q->revision,'reason'=>'Paciente desistiu'])->assertSessionHasErrors('reason');$this->flushSession();$this->actingAs($this->reception)->post(route('finance.reverse',$p->id),['reason'=>'Lançamento incorreto'])->assertForbidden();$this->flushSession();$this->actingAs($this->owner)->post(route('finance.reverse',$p->id),['reason'=>'Lançamento incorreto'])->assertSessionHasNoErrors();$this->post(route('finance.reverse',$p->id),['reason'=>'Nova tentativa'])->assertSessionHasNoErrors();$this->assertSame(1,Event::where('event','reversed')->count());$this->assertSame($i->amount_cents,$i->fresh()->balanceCents());$this->get(route('finance.receipt',$p->id))->assertOk()->assertSee('ESTORNADO');$this->post(route('finance.cancel',$q->id),['revision'=>$q->revision,'reason'=>'Paciente desistiu'])->assertSessionHasNoErrors();$this->post(route('finance.pay',$i->id),$this->payment())->assertStatus(422);}
 public function test_company_and_role_boundaries_on_reads_and_mutations():void{$q=$this->approved();$i=$q->installments->first();$this->post(route('finance.pay',$i->id),$this->payment());$p=Payment::sole();$other=Company::create(['name'=>'Outra','slug'=>'outra-fin']);$this->flushSession();$this->actingAs($this->user('owner',$other));foreach(['finance.show','finance.print'] as $route)$this->get(route($route,$q->id))->assertNotFound();$this->get(route('finance.receipt',$p->id))->assertNotFound();$this->post(route('finance.pay',$i->id),$this->payment())->assertNotFound();$this->post(route('finance.reverse',$p->id),['reason'=>'Tentativa inválida'])->assertNotFound();$this->post(route('finance.store'),$this->form())->assertNotFound();$this->get(route('finance.index',['customer_id'=>$this->patient->id]))->assertNotFound();$this->flushSession();$this->actingAs($this->dentist)->get(route('finance.index'))->assertForbidden();$this->get(route('finance.show',$q->id))->assertForbidden();$this->post(route('finance.store'),$this->form())->assertForbidden();}
 public function test_export_only_shares_commercial_summary_and_is_idempotent():void{$plan=$this->plan();$form=['base_id'=>$plan->id,'commercial_description'=>'Tratamento conforme orçamento','confirm'=>'1'];$this->flushSession();$this->actingAs($this->dentist)->post(route('treatment.export',$this->patient->id),$form)->assertSessionHasNoErrors();$this->post(route('treatment.export',$this->patient->id),$form)->assertSessionHasNoErrors();$this->assertDatabaseCount('financial_quotes',1);$q=Quote::sole();$this->assertSame(30000,$q->total_cents);$this->assertSame($plan->id,$q->source_record_id);$this->flushSession();$this->actingAs($this->owner)->get(route('finance.show',$q->id))->assertOk()->assertSee('Tratamento conforme orçamento')->assertDontSee('Procedimento secreto')->assertDontSee('Diagnóstico secreto');$this->put(route('finance.update',$q->id),['revision'=>$q->revision,'description'=>'Tratamento','gross'=>'1','discount'=>'0'])->assertSessionHasErrors('gross');$this->get(route('clinical.audit'))->assertOk()->assertSee('Orçamento encaminhado ao financeiro');}
 public function test_export_denies_unlinked_unpriced_stale_and_admin():void{$plan=$this->plan([['quantity'=>1,'unit_price_cents'=>null,'status'=>'planned']]);$form=['base_id'=>$plan->id,'commercial_description'=>'Comercial','confirm'=>'1'];$this->flushSession();$this->actingAs($this->owner)->post(route('treatment.export',$this->patient->id),$form)->assertForbidden();$this->flushSession();$this->actingAs($this->user('professional'))->post(route('treatment.export',$this->patient->id),$form)->assertNotFound();$this->flushSession();$this->actingAs($this->dentist)->post(route('treatment.export',$this->patient->id),$form)->assertSessionHasErrors('base_id');$form['base_id']=9999;$this->post(route('treatment.export',$this->patient->id),$form)->assertSessionHasErrors('base_id');$this->assertDatabaseCount('financial_quotes',0);}
 public function test_draft_revision_conflicts_and_invalid_values():void{$q=$this->quote();$form=['revision'=>$q->revision,'description'=>'Revisado','gross'=>'200','discount'=>'10'];$this->put(route('finance.update',$q->id),$form)->assertSessionHasNoErrors();$this->put(route('finance.update',$q->id),$form)->assertSessionHasErrors('revision');$this->assertSame(19000,$q->fresh()->total_cents);$bad=$this->form();$bad['gross']='1';$bad['discount']='2';$this->post(route('finance.store'),$bad)->assertSessionHasErrors('discount');$bad['gross']='-100';$this->post(route('finance.store'),$bad)->assertSessionHasErrors('gross');$form=$this->approval($q->fresh());$form['deposit']='300';$this->post(route('finance.approve',$q->id),$form)->assertSessionHasErrors('deposit');$this->assertDatabaseCount('financial_installments',0);}
 public function test_period_totals_use_payment_dates_and_due_dates_exclude_cancelled_and_reversed():void{$q=$this->approved();$i=$q->installments->first();$this->post(route('finance.pay',$i->id),$this->payment());$this->get(route('finance.index',['from'=>'2026-01-01','to'=>'2026-01-31']))->assertOk()->assertViewHas('received',1000)->assertViewHas('stats',fn($s)=>(int)$s->pending===2334);$this->post(route('finance.reverse',Payment::sole()->id),['reason'=>'Correção manual']);$this->get(route('finance.index',['from'=>'2026-01-01','to'=>'2026-01-31']))->assertOk()->assertViewHas('received',0)->assertViewHas('stats',fn($s)=>(int)$s->pending===3334);$this->post(route('finance.cancel',$q->id),['revision'=>$q->revision,'reason'=>'Cancelamento solicitado']);$this->get(route('finance.index',['from'=>'2026-01-01','to'=>'2026-01-31']))->assertOk()->assertViewHas('stats',fn($s)=>(int)$s->pending===0);}
 public function test_archived_patient_can_pay_existing_debt_but_not_approve_new_quote():void{$q=$this->approved();$draft=$this->quote();$this->patient->update(['active'=>false]);$this->post(route('finance.approve',$draft->id),$this->approval($draft))->assertStatus(422);$this->post(route('finance.pay',$q->installments->first()->id),$this->payment())->assertSessionHasNoErrors();}
}
